                children: [new Paragraph({ children: [new TextRun({ text: "Conclusion", bold: true, size: 22, font: "Arial", color: "FFFFFF" })] })] }),
              new TableCell({ borders, width: { size: 720, type: WidthType.DXA }, shading: { fill: "1F3864", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 },
                children: [new Paragraph({ children: [new TextRun({ text: "P", bold: true, size: 22, font: "Arial", color: "FFFFFF" })] })] }),
              new TableCell({ borders, width: { size: 3960, type: WidthType.DXA }, shading: { fill: "1F3864", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 },
                children: [new Paragraph({ children: [new TextRun({ text: "Primary Evidentiary Basis", bold: true, size: 22, font: "Arial", color: "FFFFFF" })] })] }),
