            new TableCell({ borders, width: { size: 4680, type: WidthType.DXA }, shading: { fill: "FFFFFF", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 },
              children: [new Paragraph({ children: [new TextRun({ text: "A. Entirely natural deformation, coincidental institutional timing", size: 22, font: "Arial" })] })] }),
